// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(this);
    address nonAdmin = address(0x1234);

    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Call setOwner with a non-admin address as argument
        // In reference, owner becomes nonAdmin; in bug, owner becomes admin
        vm.prank(admin);
        c.setOwner(nonAdmin);

        // Now attempt to call a function protected by onlyOwner as the nonAdmin
        // This will succeed on reference but revert on bug
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(admin) { ok = true; } catch { ok = false; }

        // In reference, call succeeds (ok == true); in bug, it reverts (ok == false)
        assertTrue(ok);
    }
}
